function aih_languages(): array {
    return [
        'en'=>'English','lv'=>'Latviešu','lt'=>'Lietuvių','et'=>'Eesti','sv'=>'Svenska','no'=>'Norsk','da'=>'Dansk','fi'=>'Suomi','is'=>'Íslenska',
        'pl'=>'Polski','ru'=>'Русский','uk'=>'Українська','es'=>'Español','fr'=>'Français','de'=>'Deutsch'
    ];
}

function aih_language_flags(): array {
    return [
        'en'=>'🇬🇧','lv'=>'🇱🇻','lt'=>'🇱🇹','et'=>'🇪🇪','sv'=>'🇸🇪','no'=>'🇳🇴','da'=>'🇩🇰','fi'=>'🇫🇮','is'=>'🇮🇸',
        'pl'=>'🇵🇱','ru'=>'🇷🇺','uk'=>'🇺🇦','es'=>'🇪🇸','fr'=>'🇫🇷','de'=>'🇩🇪'
    ];
}

function aih_resolve_language(array $settings): string {
    $supported=aih_languages();
    $candidate=(string)($_GET['lang'] ?? $_COOKIE['aih_lang'] ?? ($settings['ui']['language'] ?? 'en'));
    $lang=array_key_exists($candidate,$supported)?$candidate:'en';
    if(isset($_GET['lang']) && array_key_exists((string)$_GET['lang'],$supported)){
        setcookie('aih_lang',$lang,['expires'=>time()+31536000,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'httponly'=>false,'samesite'=>'Lax']);
    }
    return $lang;
}

